-- GENERATED { ALWAYS | BY DEFAULT } AS IDENTITY columns, matching PostgreSQL 18.
-- The identity value is assigned from a per-column sequence; ALWAYS rejects an
-- explicit value (unless OVERRIDING SYSTEM VALUE), BY DEFAULT accepts it
-- (OVERRIDING USER VALUE ignores it).
--
-- Distinctive names + drop up front (the differential corpora share a database).
DROP TABLE IF EXISTS idt_a;
DROP TABLE IF EXISTS idt_b;
DROP TABLE IF EXISTS idt_c;
DROP TABLE IF EXISTS idt_alt;

CREATE TABLE idt_a (id int GENERATED ALWAYS AS IDENTITY, v text);
CREATE TABLE idt_b (id int GENERATED BY DEFAULT AS IDENTITY, v text);
INSERT INTO idt_a (v) VALUES ('a'), ('b');
SELECT id, v FROM idt_a ORDER BY id;

-- ALWAYS: an explicit value is rejected (428C9); OVERRIDING SYSTEM VALUE accepts.
INSERT INTO idt_a (id, v) VALUES (100, 'x');
INSERT INTO idt_a (id, v) OVERRIDING SYSTEM VALUE VALUES (100, 'x');
SELECT id, v FROM idt_a ORDER BY id;

-- BY DEFAULT: an explicit value is accepted; OVERRIDING USER VALUE ignores it.
INSERT INTO idt_b (id, v) VALUES (50, 'y');
INSERT INTO idt_b (v) VALUES ('z');
INSERT INTO idt_b (id, v) OVERRIDING USER VALUE VALUES (999, 'uv');
SELECT id, v FROM idt_b ORDER BY id;

-- attidentity: 'a' for ALWAYS, 'd' for BY DEFAULT.
SELECT attname, attidentity FROM pg_attribute
  WHERE attrelid = 'idt_a'::regclass AND attnum > 0 ORDER BY attnum;
SELECT attname, attidentity FROM pg_attribute
  WHERE attrelid = 'idt_b'::regclass AND attnum > 0 ORDER BY attnum;

-- Identity with START WITH / INCREMENT BY.
CREATE TABLE idt_c (id int GENERATED ALWAYS AS IDENTITY (START WITH 10 INCREMENT BY 5), v text);
INSERT INTO idt_c (v) VALUES ('a'), ('b'), ('c');
SELECT id, v FROM idt_c ORDER BY id;

-- RETURNING sees the assigned identity value.
INSERT INTO idt_a (v) VALUES ('r') RETURNING id;

-- ALTER ADD IDENTITY needs the column NOT NULL (55000 otherwise); DROP IDENTITY
-- removes it, and DROP IDENTITY on a plain column is 55000 (IF EXISTS skips).
CREATE TABLE idt_alt (id int NOT NULL, v text);
ALTER TABLE idt_alt ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY;
INSERT INTO idt_alt (v) VALUES ('a'), ('b');
SELECT id, v FROM idt_alt ORDER BY id;
SELECT attidentity FROM pg_attribute WHERE attrelid = 'idt_alt'::regclass AND attname = 'id';
ALTER TABLE idt_alt ALTER COLUMN id DROP IDENTITY;
SELECT attidentity FROM pg_attribute WHERE attrelid = 'idt_alt'::regclass AND attname = 'id';
-- DROP IDENTITY on a non-identity column: 55000, suppressed by IF EXISTS.
ALTER TABLE idt_alt ALTER COLUMN id DROP IDENTITY;
ALTER TABLE idt_alt ALTER COLUMN id DROP IDENTITY IF EXISTS;

DROP TABLE idt_a;
DROP TABLE idt_b;
DROP TABLE idt_c;
DROP TABLE idt_alt;
